  private static Object unwrapEnum(Object value) {
    if (value == null || !value.getClass().isEnum()) return value;
    try {
      return value.getClass().getField("value").get(value);
    } catch (ReflectiveOperationException ignored) {
      return value;
    }
  }

  private static void assertEquals(Object expected, Object actual, String message) {
    expected = unwrapEnum(expected);
    actual = unwrapEnum(actual);
    if (expected instanceof Number expectedNumber && actual instanceof Number actualNumber) {
      if (Math.abs(expectedNumber.doubleValue() - actualNumber.doubleValue()) < 0.000001d) return;
    }
    if (expected == null ? actual != null : !expected.equals(actual)) {
      throw new AssertionError(message + ": expected " + expected + ", got " + actual);
    }
  }

  private static void assertTrue(boolean condition, String message) {
    if (!condition) throw new AssertionError(message);
  }

  private static void assertThrows(Runnable runnable, String message) {
    try {
      runnable.run();
    } catch (RuntimeException expected) {
      return;
    }
    throw new AssertionError(message);
  }
